			// the encoded byte so an encoded space ("%20") stays path content
			// and is never decoded into a direct U+0020.
			i += 2
			continue
		}
		if basePath[i] == ' ' {
			return failuref("invalid_config",
				"%s: upstream %q base path contains an unencoded space (U+0020): a space in the path must be percent-encoded as %%2520 (e.g. \"http://example.com/base%%2520path\"); the address is judged as written, so the space is neither trimmed nor replaced with an encoding",
				routeLabel(loc, id), p.raw)
		}
	}
	return nil
}

