	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			src := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"/","upstream":"` + tc.upstream + `"}]}`
			c := mustConfig(t, src)
			res := resolveJSON(t, c, `{"method":"GET","target":"`+tc.target+`"}`)
