package main

import (
	"fmt"
	"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
)

func main() {
	// route 1 upstream has a direct space (content layer); route 2 carries a
	// bad queryTransforms rule (rule layer) -> rule error must win.
	cfg1 := `{"routes":[
	  {"id":"early","methods":["GET"],"pathPrefix":"/a","upstream":"http://h/base path"},
	  {"id":"later","methods":["GET"],"pathPrefix":"/b","upstream":"http://h2",
	   "queryTransforms":[{"op":"frob","name":"x"}]}
	]}`
	if _, f := contractsentinel.ParseConfig([]byte(cfg1)); f != nil {
		fmt.Println("case1:", f.Code, "|", f.Reason)
	}

	// route 1 wrong-typed methods (type layer); route 2 space upstream (content) -> type wins.
	cfg2 := `{"routes":[
	  {"id":"a","methods":"GET","pathPrefix":"/a","upstream":"http://h"},
	  {"id":"b","methods":["GET"],"pathPrefix":"/b","upstream":"http://h/base path"}
	]}`
	if _, f := contractsentinel.ParseConfig([]byte(cfg2)); f != nil {
		fmt.Println("case2:", f.Code, "|", f.Reason)
	}

	// broken JSON beats everything
	if _, f := contractsentinel.ParseConfig([]byte(`{"routes":[{"upstream":"http://h/a b"} BROKEN`)); f != nil {
		fmt.Println("case3:", f.Code, "|", f.Reason)
	}
}
EOF
